package com.univmar.customer;
import com.univmar.common.api.ApiException; import com.univmar.customer.api.CustomerDtos.*; import com.univmar.customer.domain.*; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class CustomerService { private final CustomerRepository customers; public CustomerService(CustomerRepository customers){this.customers=customers;} public CustomerResponse create(CustomerInput input){Customer c=new Customer(input.type(),req(input.name()),trim(input.companyName()),trim(input.email()),trim(input.phone()),trim(input.notes())); append(c,input);return response(customers.save(c));} public CustomerResponse update(UUID id,CustomerInput input){Customer c=entity(id);c.update(input.type(),req(input.name()),trim(input.companyName()),trim(input.email()),trim(input.phone()),trim(input.notes()));return response(c);} public CustomerResponse addContact(UUID id,ContactInput input){Customer c=entity(id);c.addContact(new CustomerContact(c,req(input.name()),trim(input.role()),trim(input.email()),trim(input.phone())));return response(c);} public CustomerResponse addAddress(UUID id,AddressInput input){Customer c=entity(id);c.addAddress(new CustomerAddress(c,req(input.label()),req(input.line1()),trim(input.line2()),trim(input.city()),trim(input.country()),trim(input.postalCode())));return response(c);} @Transactional(readOnly=true) public CustomerResponse detail(UUID id){return response(entity(id));} @Transactional(readOnly=true) public CustomerPage list(String search,CustomerType type,Boolean active,Pageable pageable){Specification<Customer> spec=Specification.where(null);if(search!=null&&!search.isBlank()){String term="%"+search.trim().toLowerCase(Locale.ROOT)+"%";spec=spec.and((r,q,b)->b.or(b.like(b.lower(r.get("name")),term),b.like(b.lower(r.get("companyName")),term),b.like(b.lower(r.get("email")),term)));}if(type!=null)spec=spec.and((r,q,b)->b.equal(r.get("type"),type));if(active!=null)spec=spec.and((r,q,b)->b.equal(r.get("active"),active));return CustomerPage.from(customers.findAll(spec,pageable).map(this::response));} private void append(Customer c,CustomerInput i){if(i.contacts()!=null)i.contacts().forEach(x->c.addContact(new CustomerContact(c,req(x.name()),trim(x.role()),trim(x.email()),trim(x.phone()))));if(i.addresses()!=null)i.addresses().forEach(x->c.addAddress(new CustomerAddress(c,req(x.label()),req(x.line1()),trim(x.line2()),trim(x.city()),trim(x.country()),trim(x.postalCode()))));} private Customer entity(UUID id){return customers.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"CUSTOMER_NOT_FOUND","Customer was not found."));} private CustomerResponse response(Customer c){return new CustomerResponse(c.getId(),c.getType(),c.getName(),c.getCompanyName(),c.getEmail(),c.getPhone(),c.getNotes(),c.isActive(),c.getContacts().stream().map(x->new Contact(x.getId(),x.getName(),x.getRole(),x.getEmail(),x.getPhone())).toList(),c.getAddresses().stream().map(x->new Address(x.getId(),x.getLabel(),x.getLine1(),x.getLine2(),x.getCity(),x.getCountry(),x.getPostalCode())).toList());} private String trim(String v){return v==null||v.isBlank()?null:v.trim();} private String req(String v){String x=trim(v);if(x==null)throw new ApiException(HttpStatus.BAD_REQUEST,"VALIDATION_ERROR","Required value missing.");return x;} }
